insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c15', 'question', 'doubleu', null, 'du-yerin', null, null, null, array['Push timing','First payment']::text[], '{}'::text[], 'resolved', null, '{"en":{"title":"Should push opt-in prompts appear before or after the first reward?","summary":"Where you ask changes how the ask feels.","problem":"We couldn''t tell whether asking for notification permission before or after a player''s first reward moment mattered for opt-in.","tried":"Ran the same prompt copy in both positions across two matched cohorts for three weeks.","result":"After-reward placement won by a wide margin. Asking before the first reward reads as a demand; asking after reads as an invitation."},"ko":{"title":"푸시 알림 동의 요청, 첫 보상 전에 할까 후에 할까?","summary":"언제 묻는지가 어떻게 느껴지는지를 바꿉니다.","problem":"첫 보상 순간 전과 후 중 언제 알림 권한을 요청하는 게 동의율에 영향을 주는지 알 수 없었습니다.","tried":"동일한 문구로 두 위치를 매칭된 두 코호트에 3주간 테스트했습니다.","result":"보상 이후 요청이 큰 차이로 이겼습니다. 첫 보상 전 요청은 요구처럼 느껴지고, 이후 요청은 초대처럼 느껴집니다."},"de":{"title":"Sollte die Push-Opt-in-Abfrage vor oder nach der ersten Belohnung kommen?","summary":"Wann du fragst, verändert, wie sich das Fragen anfühlt.","problem":"Wir wussten nicht, ob es für die Opt-in-Rate eine Rolle spielt, ob wir vor oder nach dem ersten Belohnungsmoment um die Benachrichtigungserlaubnis bitten.","tried":"Denselben Abfragetext an beiden Stellen über zwei abgeglichene Kohorten drei Wochen lang getestet.","result":"Die Platzierung nach der Belohnung gewann deutlich. Vor der ersten Belohnung zu fragen, wirkt wie eine Forderung; danach wie eine Einladung."},"tr":{"title":"Push bildirim izni ilk ödülden önce mi sonra mı sorulmalı?","summary":"Ne zaman sorduğun, sorunun nasıl hissettirdiğini değiştiriyor.","problem":"Bildirim izni istemenin oyuncunun ilk ödül anından önce mi sonra mı gelmesinin kabul oranını etkileyip etkilemediğini bilemiyorduk.","tried":"Aynı istem metnini iki konumda, eşleştirilmiş iki kohortta üç hafta test ettik.","result":"Ödülden sonraki yerleşim büyük farkla kazandı. İlk ödülden önce sormak bir talep gibi hissettiriyor; sonrasında sormak bir davet gibi."}}'::jsonb, 'en', null, null, null, now() - interval '2 months', '{"value":2,"unit":"month"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c1', 'project', 'doubleu', null, 'du-doyoon', 'c15', 'solvedThrough', 'We stopped asking before the reward and built the reward moment first.', array['First payment','Reward moment']::text[], '{}'::text[], null, null, '{"en":{"title":"A first-payment reward flow that lifted slot conversion 12pp","summary":"A tiny reward moment before the paywall changed everything.","problem":"92% of new players never opened the payment screen during their first session.","tried":"We added a near-miss moment in the first three spins and surfaced a first-purchase 3x bonus banner right after the tutorial.","result":"First-session payment conversion rose 12 percentage points, with a lasting lift in retention. Overselling the reward copy backfired, though — churn crept back up."},"ko":{"title":"결제 화면 진입 전 작은 보상 하나로 슬롯 결제 전환율 12%p 상승","summary":"결제 화면 앞의 작은 보상 하나가 모든 걸 바꿨어요.","problem":"신규 유저의 92%가 첫 세션에서 결제 화면을 아예 열어보지 않았습니다.","tried":"첫 3회 스핀에 아쉬운 탈락 연출을 넣고, 튜토리얼 직후 첫 결제 3배 보너스 배너를 노출했습니다.","result":"첫 세션 결제 전환율이 12%p 상승했고 리텐션도 꾸준히 개선됐습니다. 다만 보상 문구를 과하게 강조하니 이탈률이 다시 슬며시 올라갔습니다."},"de":{"title":"Eine Belohnung vor dem Bezahlbildschirm steigerte die Slot-Conversion um 12 Prozentpunkte","summary":"Ein winziger Belohnungsmoment vor der Kaufwand veränderte alles.","problem":"92% der neuen Spieler öffneten in ihrer ersten Sitzung nie den Zahlungsbildschirm.","tried":"Wir bauten in den ersten drei Spins einen Beinahe-Gewinn ein und zeigten direkt nach dem Tutorial ein Banner für einen 3-fachen Erstkaufbonus.","result":"Die Zahlungs-Conversion in der ersten Sitzung stieg um 12 Prozentpunkte, mit anhaltend besserer Retention. Zu aufdringliche Bonus-Texte wirkten sich jedoch negativ aus — die Abwanderung stieg wieder leicht an."},"tr":{"title":"Ödeme ekranından önceki küçük bir ödül, slot dönüşümünü 12 puan artırdı","summary":"Ödeme duvarından önceki küçük bir ödül anı her şeyi değiştirdi.","problem":"Yeni oyuncuların %92''si ilk oturumunda ödeme ekranını hiç açmadı.","tried":"İlk üç çevirmede az farkla kaybetme anı ekledik ve öğreticinin hemen ardından ilk alışverişe özel 3 kat bonus banner''ı gösterdik.","result":"İlk oturum ödeme dönüşümü 12 puan arttı ve elde tutma oranında kalıcı bir iyileşme oldu. Ancak ödül metnini fazla abartmak geri tepti — terk oranı yeniden yükseldi."}}'::jsonb, 'en', null, null, null, now() - interval '3 days', '{"value":3,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c2', 'experiment', 'whow', null, 'wh-lena', null, null, null, array['Board size','Session length']::text[], '{}'::text[], null, null, '{"en":{"title":"Board size test for our merge game: is 6x6 really optimal?","summary":"More board doesn''t always mean more fun.","problem":"We assumed a bigger board would simply mean longer sessions, but never tested it.","tried":"Ran 6x6, 7x7, and 8x8 as parallel A/B/C cohorts for two weeks, tracking session length, churn, and clear time.","result":"7x7 won on both session length and satisfaction. 8x8 backfired — fatigue pushed early drop-off higher."},"ko":{"title":"머지 게임 보드 크기 테스트: 6x6이 정말 최선일까?","summary":"보드가 크다고 항상 더 재밌는 건 아니었습니다.","problem":"보드가 클수록 플레이 시간이 길어질 거라 막연히 가정하고 한 번도 검증하지 않았습니다.","tried":"6x6, 7x7, 8x8을 2주간 A/B/C 코호트로 동시에 운영하며 플레이 시간, 이탈률, 클리어 시간을 추적했습니다.","result":"7x7이 플레이 시간과 만족도 모두에서 우승했습니다. 8x8은 피로도 때문에 초반 이탈이 오히려 늘어 역효과가 났습니다."},"de":{"title":"Spielfeldgröße im Merge-Game getestet: Ist 6x6 wirklich optimal?","summary":"Ein größeres Feld bedeutet nicht automatisch mehr Spaß.","problem":"Wir gingen davon aus, dass ein größeres Spielfeld einfach längere Sitzungen bedeutet — ohne das je zu testen.","tried":"Wir liefen 6x6, 7x7 und 8x8 zwei Wochen lang parallel als A/B/C-Kohorten und maßen Sitzungsdauer, Abwanderung und Löschzeit.","result":"Bei Sitzungsdauer wie Zufriedenheit gewann 7x7. 8x8 ging nach hinten los — die Ermüdung erhöhte den frühen Abbruch."},"tr":{"title":"Birleştirme oyunumuz için tahta boyutu testi: 6x6 gerçekten en iyisi mi?","summary":"Daha büyük tahta her zaman daha eğlenceli demek değil.","problem":"Daha büyük bir tahtanın basitçe daha uzun oturumlar demek olduğunu varsaydık ama hiç test etmemiştik.","tried":"6x6, 7x7 ve 8x8''i iki hafta boyunca paralel A/B/C kohortları olarak çalıştırıp oturum süresini, terk oranını ve temizleme süresini izledik.","result":"7x7 hem oturum süresinde hem memnuniyette kazandı. 8x8 ise geri tepti — yorgunluk erken terk oranını artırdı."}}'::jsonb, 'en', null, null, null, now() - interval '5 days', '{"value":5,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c3', 'question', 'paxie', null, 'px-sena', null, null, null, array['Cross-promo']::text[], '{}'::text[], 'discussion', null, '{"en":{"title":"Looking for a studio to co-test cross-promo banners","summary":"We need a partner studio to test this properly.","problem":"Our own player base is too small to validate cross-promo lift with statistical confidence.","tried":"Cross-linked three of our own titles first to establish an internal click-through baseline.","result":"Landed a 1.8% baseline CTR internally. Now we''d like to test real cross-studio placement with a partner."},"ko":{"title":"크로스 프로모 배너를 함께 테스트할 스튜디오를 찾습니다","summary":"이걸 제대로 검증하려면 파트너 스튜디오가 필요합니다.","problem":"자체 유저 규모가 작아서 크로스 프로모 효과를 통계적으로 검증하기 어렵습니다.","tried":"먼저 자사 타이틀 3개를 서로 연결해 내부 클릭률 기준선을 만들었습니다.","result":"내부 기준 클릭률 1.8%를 확보했습니다. 이제 실제 스튜디오 간 배치를 파트너와 테스트해보고 싶습니다."},"de":{"title":"Suche Studio für gemeinsamen Test von Cross-Promo-Bannern","summary":"Wir brauchen ein Partnerstudio, um das richtig zu testen.","problem":"Unsere eigene Spielerbasis ist zu klein, um den Cross-Promo-Effekt statistisch belastbar zu bestätigen.","tried":"Wir verlinkten zunächst drei unserer eigenen Titel gegenseitig, um eine interne Klickrate als Basis zu ermitteln.","result":"Wir erreichten intern eine Basis-CTR von 1,8%. Jetzt möchten wir echte studioübergreifende Platzierungen mit einem Partner testen."},"tr":{"title":"Çapraz promosyon banner''larını birlikte test edecek bir stüdyo arıyoruz","summary":"Bunu düzgün test etmek için bir ortak stüdyoya ihtiyacımız var.","problem":"Kendi oyuncu tabanımız, çapraz promosyon etkisini istatistiksel güvenle doğrulamak için çok küçük.","tried":"Önce kendi üç oyunumuzu birbirine çapraz bağlayarak dahili bir tıklama oranı taban çizgisi oluşturduk.","result":"Dahili olarak %1,8 taban tıklama oranına ulaştık. Şimdi bir ortakla gerçek stüdyolar arası yerleşimi test etmek istiyoruz."}}'::jsonb, 'en', null, null, null, now() - interval '1 days', '{"value":1,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c4', 'experiment', 'doubleu', null, 'du-haeun', null, null, null, array['Push timing','Return rate']::text[], array['c1']::text[], null, null, '{"en":{"title":"Push notification timing vs. return rate","summary":"When you ask matters as much as what you send.","problem":"We were guessing at send times instead of testing them.","tried":"Split the same cohort into commute, lunch, and evening send windows over four weeks.","result":"Evening (8-9pm) sends won clearly on return rate. Commute-time pushes actually increased notification opt-outs."},"ko":{"title":"푸시 알림 발송 시간과 재방문율의 관계","summary":"무엇을 보내는지 못지않게 언제 보내는지가 중요했습니다.","problem":"발송 시간을 검증 없이 감으로 정하고 있었습니다.","tried":"동일 코호트를 출퇴근 시간, 점심시간, 저녁 시간대 발송 그룹으로 나눠 4주간 테스트했습니다.","result":"저녁(8-9시) 발송이 재방문율에서 확실히 앞섰습니다. 출퇴근 시간대 발송은 오히려 알림 수신 거부를 늘렸습니다."},"de":{"title":"Zeitpunkt von Push-Benachrichtigungen vs. Rückkehrrate","summary":"Wann du fragst, zählt genauso viel wie was du sendest.","problem":"Wir haben den Versandzeitpunkt geraten, statt ihn zu testen.","tried":"Dieselbe Kohorte wurde vier Wochen lang in Pendel-, Mittags- und Abendfenster für den Versand aufgeteilt.","result":"Abendliche Sendungen (20-21 Uhr) gewannen klar bei der Rückkehrrate. Push-Nachrichten zur Pendelzeit erhöhten sogar die Abmeldungen von Benachrichtigungen."},"tr":{"title":"Push bildirim zamanlaması ve geri dönüş oranı","summary":"Ne zaman sorduğun, ne gönderdiğin kadar önemli.","problem":"Gönderim zamanlarını test etmek yerine tahmin ediyorduk.","tried":"Aynı kohortu dört hafta boyunca işe gidiş-geliş, öğle ve akşam gönderim dilimlerine ayırdık.","result":"Akşam (20.00-21.00) gönderimleri geri dönüş oranında açık ara kazandı. İşe gidiş-geliş saatindeki bildirimler ise bildirimden çıkmaları artırdı."}}'::jsonb, 'en', null, null, null, now() - interval '1 weeks', '{"value":1,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c5', 'project', 'whow', null, 'wh-jonas', 'c1', 'appliedFrom', 'Same reward moment, moved three days before the event instead of after the tutorial.', array['Live events','Reward moment']::text[], '{}'::text[], null, null, '{"en":{"title":"A 3-day teaser beats a same-day event launch","summary":"Anticipation is a feature, not a delay.","problem":"Launching live events cold led to weak day-one participation.","tried":"Started teasing \"coming soon\" banners with reward previews three days before the event went live.","result":"Day-one participation jumped noticeably. Teasing too far in advance, though, causes its own fatigue."},"ko":{"title":"당일 오픈보다 3일 전 티저가 더 효과적이었습니다","summary":"기대감은 지연이 아니라 하나의 기능입니다.","problem":"라이브 이벤트를 예고 없이 오픈하니 첫날 참여율이 저조했습니다.","tried":"이벤트 시작 3일 전부터 보상 미리보기가 담긴 ''곧 시작'' 배너를 노출했습니다.","result":"첫날 참여율이 눈에 띄게 올랐습니다. 다만 너무 일찍부터 티저를 걸면 그 나름의 피로감이 생겼습니다."},"de":{"title":"Ein 3-tägiger Teaser schlägt einen Event-Start ohne Vorlauf","summary":"Vorfreude ist ein Feature, keine Verzögerung.","problem":"Live-Events ohne Vorankündigung zu starten führte zu schwacher Teilnahme am ersten Tag.","tried":"Wir begannen drei Tage vor Event-Start mit „Demnächst\"-Bannern inklusive Belohnungsvorschau.","result":"Die Teilnahme am ersten Tag stieg merklich. Zu früh angeteasert, entsteht allerdings eine eigene Ermüdung."},"tr":{"title":"3 günlük teaser, aynı gün etkinlik lansmanını geride bırakıyor","summary":"Beklenti bir gecikme değil, bir özelliktir.","problem":"Canlı etkinlikleri habersiz başlatmak ilk gün katılımını zayıflatıyordu.","tried":"Etkinlik başlamadan üç gün önce ödül önizlemeli ''yakında'' banner''ları göstermeye başladık.","result":"İlk gün katılımı belirgin şekilde arttı. Ancak çok erkenden teaser vermek kendi yorgunluğunu yaratıyor."}}'::jsonb, 'en', null, null, null, now() - interval '2 weeks', '{"value":2,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c6', 'project', 'paxie', null, 'px-yuna', null, null, null, array['Onboarding']::text[], array['c13']::text[], null, null, '{"en":{"title":"Delay the tutorial skip button instead of hiding it","summary":"Give players the choice — just not immediately.","problem":"Removing the skip button entirely increased early drop-off.","tried":"Kept the button, but delayed its appearance until step two instead of showing it immediately.","result":"Drop-off fell and veteran-player complaints dropped too. Offering choice without front-loading it mattered more than we expected."},"ko":{"title":"튜토리얼 건너뛰기 버튼, 숨기지 말고 늦게 보여주세요","summary":"선택지는 주되, 처음부터 주지는 않기.","problem":"건너뛰기 버튼을 아예 없앴더니 초반 이탈이 오히려 늘었습니다.","tried":"버튼은 유지하되 처음부터 보여주지 않고 두 번째 단계부터 노출되도록 지연시켰습니다.","result":"이탈률이 낮아지고 숙련 유저 불만도 줄었습니다. 선택권을 주되 처음부터 주지 않는 것이 생각보다 중요했습니다."},"de":{"title":"Den Tutorial-Skip-Button verzögern statt verstecken","summary":"Gib Spielern die Wahl — nur nicht sofort.","problem":"Den Skip-Button ganz zu entfernen erhöhte den frühen Abbruch.","tried":"Wir behielten den Button, verzögerten sein Erscheinen aber bis Schritt zwei, statt ihn sofort zu zeigen.","result":"Der Abbruch sank und auch Beschwerden erfahrener Spieler nahmen ab. Wahlfreiheit zu bieten, ohne sie vorzuziehen, war wichtiger als erwartet."},"tr":{"title":"Öğretici atlama düğmesini gizlemek yerine geciktirin","summary":"Oyunculara seçim hakkı verin — hemen değil.","problem":"Atlama düğmesini tamamen kaldırmak erken terk oranını artırdı.","tried":"Düğmeyi tuttuk ama hemen göstermek yerine ikinci adıma kadar görünmesini geciktirdik.","result":"Terk oranı düştü, deneyimli oyuncu şikayetleri de azaldı. Seçimi baştan sunmadan vermek beklediğimizden daha önemliymiş."}}'::jsonb, 'en', null, null, null, now() - interval '3 weeks', '{"value":3,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c7', 'project', 'doubleu', null, 'du-jiho', null, null, null, array['Daily rewards','Retention']::text[], array['c13']::text[], null, null, '{"en":{"title":"Rebuilding the daily login calendar around momentum, not streaks","summary":"Momentum beats punishment for daily habits.","problem":"Streak resets punished players so hard that many just stopped logging in after one miss.","tried":"Added a one-time \"grace\" token that protects a missed day, and reframed the calendar around cumulative progress instead of a hard streak counter.","result":"30-day active rate improved, and support tickets about \"losing my streak\" nearly disappeared."},"ko":{"title":"연속 출석 대신 누적 모멘텀 중심으로 출석 캘린더 재설계","summary":"매일 습관을 만드는 건 처벌보다 모멘텀입니다.","problem":"연속 출석이 끊기면 페널티가 너무 커서 한 번만 놓쳐도 접속을 아예 그만두는 유저가 많았습니다.","tried":"결석 하루를 보호해주는 1회용 ''그레이스'' 토큰을 추가하고, 엄격한 연속 카운터 대신 누적 진행도 중심으로 캘린더를 재구성했습니다.","result":"30일 활성 유저 비율이 개선됐고, ''연속 기록이 끊겼다''는 문의도 거의 사라졌습니다."},"de":{"title":"Der tägliche Login-Kalender: Schwung statt Serien","summary":"Für tägliche Gewohnheiten schlägt Schwung Bestrafung.","problem":"Das Zurücksetzen der Serie bestrafte Spieler so hart, dass viele nach nur einem verpassten Tag ganz aufhörten, sich einzuloggen.","tried":"Wir fügten ein einmaliges „Gnaden\"-Token hinzu, das einen verpassten Tag schützt, und stellten den Kalender auf kumulativen Fortschritt statt auf einen strikten Serienzähler um.","result":"Die 30-Tage-Aktivrate verbesserte sich, und Support-Anfragen zum Thema „verlorene Serie\" verschwanden fast vollständig."},"tr":{"title":"Günlük giriş takvimini seri yerine momentum üzerine kurmak","summary":"Günlük alışkanlıklarda momentum, cezadan daha etkili.","problem":"Serinin sıfırlanması oyuncuları o kadar sert cezalandırıyordu ki birçoğu tek bir günü kaçırınca girişi tamamen bırakıyordu.","tried":"Kaçırılan bir günü koruyan tek seferlik bir ''af'' jetonu ekledik ve takvimi katı bir seri sayacı yerine birikimli ilerleme etrafında yeniden kurguladık.","result":"30 günlük aktif oran arttı ve ''serimi kaybettim'' şikayetleri neredeyse tamamen ortadan kalktı."}}'::jsonb, 'en', null, null, null, now() - interval '3 weeks', '{"value":3,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c8', 'experiment', 'whow', null, 'wh-mira', null, null, null, array['Session length']::text[], array['c2']::text[], null, null, '{"en":{"title":"Does a visible progress bar change merge session length?","summary":"A smooth bar matters more than the bar itself.","problem":"We didn''t know whether showing board-completion progress actually kept players engaged longer.","tried":"A/B tested a persistent completion bar against no indicator at all across two weeks.","result":"The progress-bar group played noticeably longer sessions, but only when it filled smoothly — a stuttering animation hurt more than having none."},"ko":{"title":"진행 바를 보여주면 머지 게임 플레이 시간이 늘어날까?","summary":"바 자체보다 부드럽게 채워지는 애니메이션이 중요했습니다.","problem":"보드 완성도를 보여주는 것이 실제로 플레이 지속 시간에 도움이 되는지 알 수 없었습니다.","tried":"2주간 상시 노출되는 완성도 바와 표시가 아예 없는 그룹을 A/B 테스트했습니다.","result":"진행 바 그룹의 플레이 시간이 눈에 띄게 길었지만, 부드럽게 채워질 때만 그랬습니다. 애니메이션이 끊기면 아예 없는 것보다 더 나빴습니다."},"de":{"title":"Verändert eine sichtbare Fortschrittsleiste die Merge-Sitzungsdauer?","summary":"Eine flüssige Leiste zählt mehr als die Leiste selbst.","problem":"Wir wussten nicht, ob das Anzeigen des Baufortschritts Spieler wirklich länger bei der Stange hielt.","tried":"Wir testeten zwei Wochen lang eine dauerhaft sichtbare Fortschrittsleiste gegen gar keine Anzeige.","result":"Die Fortschrittsleisten-Gruppe spielte merklich längere Sitzungen — aber nur, wenn sie sich flüssig füllte. Eine ruckelnde Animation schadete mehr, als keine Anzeige zu haben."},"tr":{"title":"Görünür bir ilerleme çubuğu birleştirme oturum süresini değiştirir mi?","summary":"Akıcı bir çubuk, çubuğun kendisinden daha önemli.","problem":"Tahta tamamlanma ilerlemesini göstermenin oyuncuları gerçekten daha uzun süre elde tutup tutmadığını bilmiyorduk.","tried":"İki hafta boyunca kalıcı bir tamamlanma çubuğunu hiç gösterge olmamasına karşı A/B testine tabi tuttuk.","result":"İlerleme çubuğu grubu belirgin şekilde daha uzun oturumlar oynadı, ama yalnızca akıcı doluyorsa. Takılan animasyon, hiç olmamasından daha kötüydü."}}'::jsonb, 'en', null, null, null, now() - interval '4 weeks', '{"value":4,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c9', 'experiment', 'paxie', null, 'px-marco', 'c1', 'inspiredBy', 'Took the reward moment and asked how fast it can be before it stops landing.', array['Reward moment']::text[], '{}'::text[], null, null, '{"en":{"title":"Testing reward reveal speed in casual puzzle levels","summary":"Faster isn''t always worse for satisfaction.","problem":"Reward animations felt like they were slowing down the core loop, but we hadn''t measured it.","tried":"Compared a 0.6s reward reveal against a 1.4s version across matched cohorts.","result":"The faster reveal increased levels-per-session with no drop in perceived reward satisfaction from surveys."},"ko":{"title":"캐주얼 퍼즐 레벨의 보상 연출 속도 테스트","summary":"빠르다고 항상 만족도가 떨어지는 건 아니었습니다.","problem":"보상 애니메이션이 핵심 루프를 느리게 만드는 것 같았지만 실제로 측정한 적은 없었습니다.","tried":"동일 조건의 코호트로 0.6초와 1.4초 보상 연출을 비교했습니다.","result":"빠른 연출이 세션당 클리어 레벨 수를 늘렸고, 설문상 체감 보상 만족도는 떨어지지 않았습니다."},"de":{"title":"Test der Belohnungs-Reveal-Geschwindigkeit in Casual-Puzzle-Leveln","summary":"Schneller ist bei der Zufriedenheit nicht immer schlechter.","problem":"Belohnungsanimationen fühlten sich an, als würden sie den Kern-Loop verlangsamen, aber wir hatten es nie gemessen.","tried":"Wir verglichen ein 0,6-Sekunden-Reveal mit einer 1,4-Sekunden-Version über abgeglichene Kohorten hinweg.","result":"Das schnellere Reveal erhöhte die Level pro Sitzung, ohne dass die gefühlte Belohnungszufriedenheit in Umfragen sank."},"tr":{"title":"Rahat bulmaca seviyelerinde ödül açılış hızını test etmek","summary":"Daha hızlı olmak memnuniyet için her zaman kötü değil.","problem":"Ödül animasyonlarının ana döngüyü yavaşlattığını hissediyorduk ama hiç ölçmemiştik.","tried":"Eşleştirilmiş kohortlarda 0,6 saniyelik ödül açılışını 1,4 saniyelik versiyonla karşılaştırdık.","result":"Daha hızlı açılış, oturum başına seviye sayısını artırdı ve anketlerde algılanan ödül memnuniyetinde düşüş olmadı."}}'::jsonb, 'en', null, null, null, now() - interval '1 months', '{"value":1,"unit":"month"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c10', 'question', 'doubleu', null, 'du-soomin', null, null, null, array['Responsible gaming']::text[], '{}'::text[], 'open', 'whow', '{"en":{"title":"Seeking partners to benchmark responsible-gaming UX patterns","summary":"Supportive framing needs a shared benchmark.","problem":"We want our spend-limit and cool-down prompts to feel supportive, not punitive, but we only have our own data to compare against.","tried":"Documented our current prompt copy, timing, and opt-in rates as a starting baseline.","result":"Baseline opt-in sits at 34%. Looking for other studios willing to compare approaches and share what actually reduces player frustration.","conversation":["We want our spend-limit and cool-down prompts to feel supportive, not punitive, but we only have our own data to compare against. Anyone willing to compare notes?","We ran something similar last year — happy to share our opt-in copy if it helps as a starting point.","That would help a lot. Did you test the timing of the prompt too, or just the wording?","Mostly wording so far. Timing is still a guess on our side — we show it right after a loss streak.","Same here. Maybe that''s worth testing together instead of separately."],"brief":{"currentIssue":"DoubleU wants spend-limit/cool-down prompts that read as supportive, not punitive, but has no external benchmark to compare against.","keyIdeas":["Whow has existing prompt copy it can share as a starting point.","Both studios currently guess at prompt timing rather than testing it."],"openPoints":["Whether timing (not just wording) should be tested jointly.","No shared definition yet of what \"supportive\" actually means in practice."],"nextAction":"Whow to share its current prompt copy; both studios to scope a joint timing test."}},"ko":{"title":"책임 있는 게임 UX 패턴을 함께 비교할 파트너를 찾습니다","summary":"지지적인 톤을 만들려면 비교할 기준이 필요합니다.","problem":"지출 한도·쿨다운 안내가 처벌이 아닌 지지처럼 느껴지길 바라지만, 비교할 데이터가 자사 것뿐입니다.","tried":"현재 사용 중인 안내 문구, 노출 시점, 동의율을 정리해 기준선으로 삼았습니다.","result":"기준 동의율은 34%입니다. 접근 방식을 비교하고 실제로 유저 불만을 줄이는 방법을 공유할 스튜디오를 찾고 있습니다.","conversation":["지출 한도·쿨다운 안내가 처벌이 아닌 지지처럼 느껴지길 바라지만, 비교할 데이터가 저희 것뿐이에요. 같이 비교해볼 곳 있을까요?","저희도 작년에 비슷한 걸 해봤어요 — 참고가 되신다면 저희 동의 안내 문구를 공유해드릴 수 있어요.","정말 도움이 될 것 같아요. 문구뿐 아니라 노출 시점도 테스트해보셨나요?","문구 위주로만 해봤어요. 시점은 저희도 감으로 정해서, 연패 직후에 보여주고 있어요.","저희도 마찬가지예요. 이건 따로따로 하지 말고 같이 테스트해보는 게 나을 것 같아요."],"brief":{"currentIssue":"DoubleU는 지출 한도·쿨다운 안내가 처벌이 아닌 지지처럼 느껴지길 원하지만, 비교할 외부 기준이 없습니다.","keyIdeas":["Whow가 참고할 만한 기존 안내 문구를 갖고 있습니다.","두 스튜디오 모두 노출 시점은 아직 테스트 없이 감으로 정하고 있습니다."],"openPoints":["문구뿐 아니라 시점도 함께 테스트할지가 아직 정해지지 않았습니다.","''지지적''이라는 게 실제로 무엇을 뜻하는지에 대한 공통 기준이 없습니다."],"nextAction":"Whow가 현재 안내 문구를 공유하고, 두 스튜디오가 함께 시점 테스트 범위를 정하기로 함."}},"de":{"title":"Suche Partner zum Benchmarking von Responsible-Gaming-UX-Mustern","summary":"Ein unterstützender Ton braucht einen gemeinsamen Vergleichsmaßstab.","problem":"Unsere Ausgabenlimit- und Cool-down-Hinweise sollen unterstützend statt strafend wirken, aber wir haben nur eigene Daten zum Vergleich.","tried":"Wir dokumentierten unsere aktuellen Hinweistexte, deren Timing und Opt-in-Raten als Ausgangsbasis.","result":"Die Basis-Opt-in-Rate liegt bei 34%. Wir suchen andere Studios, die Ansätze vergleichen und teilen möchten, was Spielerfrust wirklich reduziert.","conversation":["Unsere Ausgabenlimit- und Cool-down-Hinweise sollen unterstützend statt strafend wirken, aber wir haben nur eigene Daten zum Vergleich. Hat jemand Lust, sich dazu auszutauschen?","Wir haben letztes Jahr etwas Ähnliches gemacht — gerne teilen wir unsere Hinweistexte als Ausgangspunkt.","Das würde sehr helfen. Habt ihr auch das Timing des Hinweises getestet, oder nur den Wortlaut?","Bisher hauptsächlich den Wortlaut. Beim Timing raten wir noch — wir zeigen ihn direkt nach einer Verlustserie.","Bei uns genauso. Vielleicht lohnt es sich, das gemeinsam statt getrennt zu testen."],"brief":{"currentIssue":"DoubleU möchte, dass Ausgabenlimit-/Cool-down-Hinweise unterstützend statt strafend wirken, hat aber keinen externen Vergleichsmaßstab.","keyIdeas":["Whow hat bestehende Hinweistexte, die als Ausgangspunkt dienen können.","Beide Studios raten aktuell beim Timing der Hinweise, statt es zu testen."],"openPoints":["Ob neben dem Wortlaut auch das Timing gemeinsam getestet werden soll.","Noch keine gemeinsame Definition, was \"unterstützend\" in der Praxis bedeutet."],"nextAction":"Whow teilt seine aktuellen Hinweistexte; beide Studios planen gemeinsam einen Timing-Test."}},"tr":{"title":"Sorumlu oyun UX kalıplarını kıyaslamak için ortaklar arıyoruz","summary":"Destekleyici bir ton için ortak bir kıyaslama gerekir.","problem":"Harcama limiti ve soğuma süresi uyarılarımızın cezalandırıcı değil destekleyici hissettirmesini istiyoruz ama karşılaştıracak yalnızca kendi verimiz var.","tried":"Mevcut uyarı metinlerimizi, zamanlamasını ve kabul oranlarını taban çizgisi olarak belgeledik.","result":"Taban kabul oranı %34. Yaklaşımları karşılaştırmak ve oyuncu hayal kırıklığını gerçekten azaltan yöntemleri paylaşmak isteyen stüdyolar arıyoruz.","conversation":["Harcama limiti ve soğuma süresi uyarılarımızın cezalandırıcı değil destekleyici hissettirmesini istiyoruz ama karşılaştıracak yalnızca kendi verimiz var. Karşılaştırmak isteyen var mı?","Biz geçen yıl benzer bir şey yaptık — başlangıç noktası olması için uyarı metnimizi paylaşabiliriz.","Bu çok yardımcı olur. Zamanlamayı da test ettiniz mi yoksa sadece metni mi?","Şimdiye kadar çoğunlukla metni. Zamanlama bizde de tahmin — kayıp serisinden hemen sonra gösteriyoruz.","Bizde de aynı. Belki bunu ayrı ayrı değil birlikte test etmek daha mantıklı olur."],"brief":{"currentIssue":"DoubleU, harcama limiti/soğuma süresi uyarılarının cezalandırıcı değil destekleyici hissettirmesini istiyor ama karşılaştıracak dış bir kıyas noktası yok.","keyIdeas":["Whow''un başlangıç noktası olarak paylaşabileceği mevcut uyarı metinleri var.","İki stüdyo da şu anda uyarı zamanlamasını test etmek yerine tahmin ediyor."],"openPoints":["Metnin yanı sıra zamanlamanın da birlikte test edilip edilmeyeceği belli değil.","\"Destekleyici\" kelimesinin pratikte ne anlama geldiğine dair ortak bir tanım yok."],"nextAction":"Whow mevcut uyarı metnini paylaşacak; iki stüdyo birlikte bir zamanlama testi kapsamı belirleyecek."}}}'::jsonb, 'en', '[{"author":"Soomin Jang","studio":"doubleu","timeValue":1,"timeUnit":"month"},{"author":"Lena Fischer","studio":"whow","timeValue":3,"timeUnit":"week"},{"author":"Soomin Jang","studio":"doubleu","timeValue":3,"timeUnit":"week"},{"author":"Mira Keller","studio":"whow","timeValue":2,"timeUnit":"week"},{"author":"Soomin Jang","studio":"doubleu","timeValue":2,"timeUnit":"week"}]'::jsonb, null, null, now() - interval '1 months', '{"value":1,"unit":"month"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c11', 'project', 'whow', null, 'wh-lena', null, null, null, array['Localisation','Live events']::text[], '{}'::text[], null, null, '{"en":{"title":"Localized event names outperform direct translations","summary":"Translate the feeling, not just the words.","problem":"Event names translated literally from English felt flat in some regions.","tried":"Rewrote event titles per region with local idioms instead of direct translation, keeping the same mechanics.","result":"Click-through on event banners improved in every localized region we tested, most of all in Southeast Asia."},"ko":{"title":"직역보다 현지화된 이벤트 이름이 성과가 좋았습니다","summary":"단어가 아니라 느낌을 번역하세요.","problem":"영어를 그대로 직역한 이벤트 이름이 일부 지역에서 밋밋하게 느껴졌습니다.","tried":"기획은 그대로 두고 지역별로 현지 관용 표현을 살려 이벤트 제목을 다시 지었습니다.","result":"테스트한 모든 현지화 지역에서 이벤트 배너 클릭률이 개선됐고, 동남아시아에서 가장 큰 효과를 봤습니다."},"de":{"title":"Lokalisierte Event-Namen schlagen direkte Übersetzungen","summary":"Übersetze das Gefühl, nicht nur die Worte.","problem":"Wörtlich aus dem Englischen übersetzte Event-Namen wirkten in manchen Regionen flach.","tried":"Wir schrieben Event-Titel pro Region mit lokalen Redewendungen neu, statt sie direkt zu übersetzen, und behielten dieselbe Mechanik bei.","result":"Die Klickrate auf Event-Banner verbesserte sich in jeder getesteten lokalisierten Region, am stärksten in Südostasien."},"tr":{"title":"Yerelleştirilmiş etkinlik adları doğrudan çevirilerden daha iyi performans gösteriyor","summary":"Kelimeleri değil, hissi çevirin.","problem":"İngilizceden birebir çevrilen etkinlik adları bazı bölgelerde sönük kalıyordu.","tried":"Aynı mekanikleri koruyarak etkinlik başlıklarını bölgeye göre yerel deyimlerle yeniden yazdık, birebir çeviri yapmadık.","result":"Test ettiğimiz her yerelleştirilmiş bölgede etkinlik banner tıklama oranı arttı, en çok Güneydoğu Asya''da."}}'::jsonb, 'en', null, null, null, now() - interval '5 weeks', '{"value":5,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c12', 'experiment', 'paxie', null, 'px-yuna', null, null, null, array['Trust']::text[], array['c11']::text[], null, null, '{"en":{"title":"Does an end-of-level studio credit build trust?","summary":"Credit might build trust more than metrics show.","problem":"Players had no visibility into which team built the content they were enjoying.","tried":"Added a subtle \"crafted by Paxie\" credit line at the end of each level for one cohort.","result":"No measurable change in retention, but qualitative feedback mentioned trust and craft more often — we''re still deciding if it''s worth the screen space."},"ko":{"title":"레벨 종료 시 스튜디오 크레딧 표기가 신뢰도를 높일까?","summary":"크레딧은 지표보다 더 많은 신뢰를 만들 수도 있습니다.","problem":"유저들은 자신이 즐기는 콘텐츠를 어느 팀이 만들었는지 전혀 알 수 없었습니다.","tried":"한 코호트에 한해 각 레벨 종료 시 ''Crafted by Paxie''라는 은은한 크레딧 문구를 추가했습니다.","result":"리텐션에는 측정 가능한 변화가 없었지만, 정성 피드백에서 신뢰와 정성에 대한 언급이 늘었습니다. 화면 공간을 내줄 가치가 있는지는 아직 고민 중입니다."},"de":{"title":"Schafft ein Studio-Credit am Levelende Vertrauen?","summary":"Ein Credit könnte mehr Vertrauen schaffen, als Kennzahlen zeigen.","problem":"Spieler hatten keine Sichtbarkeit darüber, welches Team die Inhalte gemacht hat, die sie genossen.","tried":"Wir fügten für eine Kohorte am Ende jedes Levels eine dezente „Crafted by Paxie\"-Credit-Zeile hinzu.","result":"Keine messbare Veränderung bei der Retention, aber qualitatives Feedback erwähnte häufiger Vertrauen und Handwerk — wir entscheiden noch, ob es den Bildschirmplatz wert ist."},"tr":{"title":"Seviye sonundaki stüdyo kredisi güven inşa eder mi?","summary":"Kredi, metriklerin gösterdiğinden daha fazla güven yaratabilir.","problem":"Oyuncuların, keyif aldıkları içeriği hangi ekibin yaptığına dair hiçbir görünürlüğü yoktu.","tried":"Bir kohort için her seviyenin sonuna sade bir ''Paxie tarafından yapıldı'' kredi satırı ekledik.","result":"Elde tutmada ölçülebilir bir değişiklik olmadı, ama nitel geri bildirimlerde güven ve emek daha sık dile getirildi — ekran alanına değip değmediğine hâlâ karar veriyoruz."}}'::jsonb, 'en', null, null, null, now() - interval '6 weeks', '{"value":6,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c13', 'experiment', 'doubleu', null, 'du-minji', null, null, null, array['Onboarding','Retention']::text[], '{}'::text[], null, null, '{"en":{"title":"Shortening onboarding by one screen","summary":"One fewer screen, one fewer excuse to leave.","problem":"Our five-screen onboarding had a steep drop-off between screens three and four.","tried":"Merged two screens into one and moved permission requests later in the flow.","result":"Onboarding completion rose meaningfully, though it took a few iterations to avoid feeling rushed."},"ko":{"title":"온보딩 화면 하나 줄이기","summary":"화면 하나가 줄면 이탈할 이유도 하나 줄어듭니다.","problem":"5단계 온보딩에서 3-4단계 사이 이탈이 유독 심했습니다.","tried":"두 화면을 하나로 합치고, 권한 요청은 플로우 뒤쪽으로 옮겼습니다.","result":"온보딩 완료율이 눈에 띄게 올랐습니다. 다만 서두르는 느낌을 없애기까지 몇 번의 조정이 필요했습니다."},"de":{"title":"Onboarding um einen Bildschirm verkürzt","summary":"Ein Bildschirm weniger, ein Grund weniger zu gehen.","problem":"Unser fünfstufiges Onboarding hatte einen starken Abbruch zwischen Bildschirm drei und vier.","tried":"Wir führten zwei Bildschirme zusammen und verschoben Berechtigungsanfragen weiter nach hinten im Ablauf.","result":"Der Onboarding-Abschluss stieg spürbar, auch wenn es ein paar Anläufe brauchte, damit es sich nicht gehetzt anfühlte."},"tr":{"title":"Katılım sürecini bir ekran kısaltmak","summary":"Bir ekran daha az, ayrılmak için bir bahane daha az.","problem":"Beş ekranlı katılım sürecimizde üçüncü ve dördüncü ekran arasında sert bir düşüş vardı.","tried":"İki ekranı birleştirdik ve izin isteklerini akışın daha ilerisine taşıdık.","result":"Katılım tamamlama oranı belirgin şekilde arttı, ancak aceleci hissettirmemesi için birkaç iterasyon gerekti."}}'::jsonb, 'en', null, null, null, now() - interval '2 months', '{"value":2,"unit":"month"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c14', 'question', 'whow', null, 'wh-tobias', null, null, null, array['Live events']::text[], '{}'::text[], 'discussion', 'doubleu', '{"en":{"title":"What''s the right cooldown between two back-to-back live events?","summary":"Running events too close together seems to cost the second one.","problem":"Back-to-back live events seem to cannibalize participation in the second one, but we don''t know how much gap actually fixes it.","tried":"Tried a 2-day gap once and a 5-day gap another time, informally — no controlled comparison yet.","result":"","conversation":["Running two live events back-to-back seems to hurt the second one''s turnout, but we don''t have real data on how much gap is enough.","We noticed the same. Anecdotally 3+ days feels safer than 1-2.","We ran ours 5 days apart once and it did fine, but that''s one data point.","Could be worth comparing calendars from last quarter across both studios.","I can pull our event calendar and turnout numbers for that.","Same — I''ll put together ours by end of week."],"brief":{"currentIssue":"Whow suspects back-to-back live events cannibalize the second event''s turnout, but the right cooldown gap is unconfirmed.","keyIdeas":["Informal signal points to 3+ days being safer than 1-2.","DoubleU has one data point at a 5-day gap that performed fine."],"openPoints":["No shared dataset yet — the comparison so far is anecdotal.","Unclear whether the right gap depends on event type or size."],"nextAction":"Both studios are pulling last quarter''s event calendar and turnout numbers to compare directly."}},"ko":{"title":"연속 라이브 이벤트 사이에 얼마나 간격을 둬야 할까?","summary":"이벤트를 너무 붙여서 열면 둘째 이벤트가 손해를 봅니다.","problem":"라이브 이벤트를 연달아 열면 두 번째 이벤트 참여율이 깎이는 것 같은데, 얼마나 간격을 둬야 하는지 모릅니다.","tried":"한 번은 2일, 한 번은 5일 간격을 비공식적으로 시도해봤을 뿐, 아직 제대로 비교해보지 않았습니다.","result":"","conversation":["라이브 이벤트를 연달아 열면 두 번째 이벤트 참여율이 깎이는 것 같은데, 얼마나 간격을 둬야 충분한지 실제 데이터가 없어요.","저희도 비슷하게 느꼈어요. 체감상 1-2일보다는 3일 이상이 안전한 것 같아요.","저희는 한 번 5일 간격으로 해봤는데 괜찮았어요, 다만 사례가 하나뿐이라서요.","지난 분기 캘린더를 두 스튜디오끼리 비교해보는 것도 좋을 것 같아요.","저희 쪽 이벤트 캘린더랑 참여율 데이터를 뽑아볼게요.","저희도 이번 주 안으로 정리해서 공유할게요."],"brief":{"currentIssue":"Whow는 연속 라이브 이벤트가 두 번째 이벤트의 참여율을 깎는다고 의심하지만, 적정 간격은 아직 확인되지 않았습니다.","keyIdeas":["체감상 1-2일보다 3일 이상이 더 안전하다는 신호가 있습니다.","DoubleU는 5일 간격으로 한 번 시도했고 결과가 괜찮았습니다."],"openPoints":["아직 공유된 데이터셋 없이 경험적 판단에만 의존하고 있습니다.","적정 간격이 이벤트 종류나 규모에 따라 달라지는지는 불확실합니다."],"nextAction":"두 스튜디오가 지난 분기 이벤트 캘린더와 참여율 데이터를 뽑아 직접 비교하기로 함."}},"de":{"title":"Wie viel Abstand braucht es zwischen zwei Live-Events hintereinander?","summary":"Events zu dicht hintereinander scheint dem zweiten zu schaden.","problem":"Live-Events kurz hintereinander scheinen die Teilnahme am zweiten zu schmälern, aber wir wissen nicht, wie viel Abstand das wirklich behebt.","tried":"Einmal informell 2 Tage, einmal 5 Tage Abstand versucht — noch kein kontrollierter Vergleich.","result":"","conversation":["Zwei Live-Events kurz hintereinander scheinen der Teilnahme am zweiten zu schaden, aber wir haben keine echten Daten dazu, wie viel Abstand reicht.","Das haben wir auch bemerkt. Gefühlt sind 3+ Tage sicherer als 1-2.","Wir hatten einmal 5 Tage Abstand und es lief gut, aber das ist nur ein Datenpunkt.","Könnte sich lohnen, die Kalender vom letzten Quartal zwischen beiden Studios zu vergleichen.","Ich kann unseren Event-Kalender und die Teilnahmezahlen dafür raussuchen.","Gleiches bei uns — ich stelle unsere bis Ende der Woche zusammen."],"brief":{"currentIssue":"Whow vermutet, dass Live-Events kurz hintereinander die Teilnahme am zweiten Event schmälern, der richtige Abstand ist aber unbestätigt.","keyIdeas":["Gefühlt sind 3+ Tage Abstand sicherer als 1-2.","DoubleU hat einen Datenpunkt mit 5 Tagen Abstand, der gut lief."],"openPoints":["Noch kein gemeinsamer Datensatz — der Vergleich ist bisher anekdotisch.","Unklar, ob der richtige Abstand von Event-Typ oder -Größe abhängt."],"nextAction":"Beide Studios stellen die Event-Kalender und Teilnahmezahlen des letzten Quartals für einen direkten Vergleich zusammen."}},"tr":{"title":"Art arda iki canlı etkinlik arasında ne kadar boşluk olmalı?","summary":"Etkinlikleri çok yakın açmak ikincisine zarar veriyor gibi.","problem":"Art arda canlı etkinlikler ikincinin katılımını düşürüyor gibi görünüyor, ama gerçekte ne kadar boşluk gerektiğini bilmiyoruz.","tried":"Bir kez 2 gün, bir kez 5 gün boşluk denedik ama gayri resmi — henüz kontrollü bir karşılaştırma yok.","result":"","conversation":["İki canlı etkinliği art arda açmak ikincisinin katılımına zarar veriyor gibi görünüyor, ama ne kadar boşluğun yeterli olduğuna dair gerçek verimiz yok.","Biz de aynısını fark ettik. Hissi olarak 1-2 günden çok 3+ gün daha güvenli.","Biz bir kez 5 gün ara verdik ve iyi gitti, ama bu tek bir veri noktası.","İki stüdyonun geçen çeyrekteki takvimlerini karşılaştırmak faydalı olabilir.","Kendi etkinlik takvimimizi ve katılım rakamlarımızı çıkarabilirim.","Biz de aynısını hafta sonuna kadar hazırlarız."],"brief":{"currentIssue":"Whow, art arda canlı etkinliklerin ikinci etkinliğin katılımını düşürdüğünden şüpheleniyor, ama doğru boşluk süresi henüz doğrulanmadı.","keyIdeas":["Hissi olarak 1-2 günden çok 3+ gün daha güvenli görünüyor.","DoubleU''nun 5 günlük boşlukla iyi giden bir veri noktası var."],"openPoints":["Henüz ortak bir veri seti yok — karşılaştırma şimdilik gözleme dayalı.","Doğru boşluğun etkinlik türüne veya büyüklüğüne bağlı olup olmadığı belirsiz."],"nextAction":"İki stüdyo da geçen çeyreğin etkinlik takvimini ve katılım rakamlarını doğrudan karşılaştırmak için çıkarıyor."}}}'::jsonb, 'en', '[{"author":"Tobias Lang","studio":"whow","timeValue":4,"timeUnit":"day"},{"author":"Jonas Weber","studio":"whow","timeValue":3,"timeUnit":"day"},{"author":"Doyoon Kim","studio":"doubleu","timeValue":3,"timeUnit":"day"},{"author":"Tobias Lang","studio":"whow","timeValue":2,"timeUnit":"day"},{"author":"Haeun Lee","studio":"doubleu","timeValue":1,"timeUnit":"day"},{"author":"Jonas Weber","studio":"whow","timeValue":1,"timeUnit":"day"}]'::jsonb, null, null, now() - interval '4 days', '{"value":4,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c16', 'project', 'whow', null, 'wh-team', null, null, null, array['Studio drop']::text[], '{}'::text[], null, null, '{"en":{"title":"July Studio Drop — Whow Games","summary":"What we built, what failed, and what we learned this month.","problem":"Monthly progress was scattered across standups and Slack threads, with no single place for the rest of the company to see it.","tried":"Shipped a new merge-event calendar, tested three onboarding variants, and reworked the daily login rewards.","result":"The onboarding rework is the clear winner and rolls out company-wide next month. The merge-event calendar underperformed and is getting cut."},"ko":{"title":"7월 스튜디오 드롭 — Whow Games","summary":"이번 달 만든 것, 실패한 것, 배운 것.","problem":"매달의 진행 상황이 스탠드업과 슬랙 대화방에 흩어져 있어서, 회사 전체가 한눈에 볼 곳이 없었습니다.","tried":"새 머지 이벤트 캘린더를 출시하고, 온보딩 3가지 버전을 테스트했고, 일일 로그인 보상을 다시 설계했습니다.","result":"온보딩 개편이 확실한 승자로, 다음 달 전사 적용됩니다. 머지 이벤트 캘린더는 성과가 낮아 폐기하기로 했습니다."},"de":{"title":"Studio Drop im Juli — Whow Games","summary":"Was wir gebaut haben, was gescheitert ist, und was wir diesen Monat gelernt haben.","problem":"Der monatliche Fortschritt war über Standups und Slack-Threads verstreut, ohne einen Ort, an dem der Rest des Unternehmens ihn sehen konnte.","tried":"Wir haben einen neuen Merge-Event-Kalender veröffentlicht, drei Onboarding-Varianten getestet und die täglichen Login-Belohnungen überarbeitet.","result":"Die überarbeitete Onboarding-Version ist der klare Gewinner und geht nächsten Monat unternehmensweit live. Der Merge-Event-Kalender lief schlecht und wird gestrichen."},"tr":{"title":"Temmuz Studio Drop — Whow Games","summary":"Bu ay ne yaptık, ne başarısız oldu ve ne öğrendik.","problem":"Aylık ilerleme standup toplantılarına ve Slack konuşmalarına dağılmıştı; şirketin geri kalanının görebileceği tek bir yer yoktu.","tried":"Yeni bir birleştirme etkinliği takvimi yayınladık, üç farklı katılım sürecini test ettik ve günlük giriş ödüllerini yeniden tasarladık.","result":"Katılım süreci yeniden tasarımı açık ara kazanan oldu ve önümüzdeki ay şirket genelinde uygulanacak. Etkinlik takvimi beklenenin altında kaldı ve iptal ediliyor."}}'::jsonb, 'en', null, null, null, now() - interval '6 days', '{"value":6,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('c17', 'project', 'doubleu', null, 'du-team', null, null, null, array['Creative relay']::text[], '{}'::text[], null, null, '{"en":{"title":"Creative Relay #01","summary":"Started by DoubleU Games · Continued by Whow Games.","problem":"Good half-finished ideas usually die inside one studio instead of getting a second look from another.","tried":"DoubleU posted a rough concept for a co-op mini-event; Whow Games picked it up and reworked the reward structure around it.","result":"The reworked version is now in Whow''s test build — passing it forward again to see how far it travels."},"ko":{"title":"크리에이티브 릴레이 #01","summary":"DoubleU Games가 시작 · Whow Games가 이어감.","problem":"좋은 아이디어라도 반쯤 완성된 상태에서 한 스튜디오 안에만 머물다 사라지는 경우가 많습니다.","tried":"DoubleU가 협동 미니 이벤트의 초안 컨셉을 올렸고, Whow Games가 이를 이어받아 보상 구조를 다시 설계했습니다.","result":"다시 설계된 버전이 지금 Whow의 테스트 빌드에 들어가 있습니다 — 이걸 또 다음 스튜디오로 넘겨볼 예정입니다."},"de":{"title":"Creative Relay #01","summary":"Gestartet von DoubleU Games · Fortgeführt von Whow Games.","problem":"Gute halbfertige Ideen sterben meist innerhalb eines Studios, statt von einem anderen noch einmal aufgegriffen zu werden.","tried":"DoubleU postete ein grobes Konzept für ein Koop-Mini-Event; Whow Games griff es auf und überarbeitete die Belohnungsstruktur.","result":"Die überarbeitete Version steckt jetzt in Whows Testbuild — wir geben sie als Nächstes weiter, um zu sehen, wie weit sie kommt."},"tr":{"title":"Creative Relay #01","summary":"DoubleU Games tarafından başlatıldı · Whow Games tarafından sürdürüldü.","problem":"İyi ama yarım kalmış fikirler genellikle başka bir stüdyo tarafından ele alınmak yerine tek bir stüdyoda kaybolup gidiyor.","tried":"DoubleU, bir kooperatif mini etkinlik için kabaca bir konsept paylaştı; Whow Games bunu devraldı ve ödül yapısını yeniden tasarladı.","result":"Yeniden tasarlanan versiyon şu anda Whow''un test sürümünde — ne kadar ileri gidebileceğini görmek için tekrar başka bir stüdyoya devredilecek."}}'::jsonb, 'en', null, null, null, now() - interval '2 weeks', '{"value":2,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('u1', 'update', 'whow', null, 'wh-bengt-larsson', 'c5', 'continuedFrom', 'The teaser worked; the countdown on the reward screen is the part still fighting us.', array['Daily rewards']::text[], '{}'::text[], null, null, '{"en":{"title":"Rebuilding the daily-reward screen — the timer is the whole fight","summary":"Rebuilding the daily-reward screen — the timer is the whole fight","note":"Rebuilding the daily-reward screen this week. The countdown timer is turning out to be the whole design problem: too prominent and it nags, too quiet and nobody comes back."},"ko":{"title":"일일 보상 화면을 다시 만드는 중 — 타이머가 전부","summary":"일일 보상 화면을 다시 만드는 중 — 타이머가 전부","note":"이번 주에 일일 보상 화면을 다시 만들고 있어요. 카운트다운 타이머가 사실상 디자인 문제 전부예요. 너무 눈에 띄면 잔소리 같고, 너무 조용하면 아무도 안 돌아와요."},"de":{"title":"Bauen den Daily-Reward-Screen neu — der Timer ist das ganze Problem","summary":"Bauen den Daily-Reward-Screen neu — der Timer ist das ganze Problem","note":"Wir bauen diese Woche den Daily-Reward-Screen neu. Der Countdown-Timer ist praktisch das gesamte Designproblem: zu präsent und er nervt, zu leise und niemand kommt zurück."},"tr":{"title":"Günlük ödül ekranını yeniden yapıyoruz — mesele tamamen sayaç","summary":"Günlük ödül ekranını yeniden yapıyoruz — mesele tamamen sayaç","note":"Bu hafta günlük ödül ekranını yeniden yapıyoruz. Geri sayım sayacı aslında tasarım probleminin tamamı: fazla belirgin olursa dırdır gibi, fazla sessiz olursa kimse dönmüyor."}}'::jsonb, 'en', null, null, null, now() - interval '1 days', '{"value":1,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('u2', 'update', 'doubleu', null, 'du-haeun', null, null, null, array['Onboarding']::text[], '{}'::text[], null, null, '{"en":{"title":"Trying a shorter tutorial. Day-2 numbers look odd so far","summary":"Trying a shorter tutorial. Day-2 numbers look odd so far","note":"Trying a much shorter tutorial. Day-2 return looks fine but day-3 dropped, so we may just have moved the drop-off rather than removed it. Watching it another week before we say anything."},"ko":{"title":"튜토리얼을 확 줄여봤는데 2일차 숫자가 이상해요","summary":"튜토리얼을 확 줄여봤는데 2일차 숫자가 이상해요","note":"튜토리얼을 많이 줄여봤어요. 2일차 복귀는 괜찮은데 3일차가 떨어져서, 이탈을 없앤 게 아니라 옮긴 것일 수도 있어요. 일주일 더 보고 얘기하려고요."},"de":{"title":"Kürzeres Tutorial im Test. Die Tag-2-Zahlen sehen seltsam aus","summary":"Kürzeres Tutorial im Test. Die Tag-2-Zahlen sehen seltsam aus","note":"Wir testen ein deutlich kürzeres Tutorial. Tag 2 sieht gut aus, aber Tag 3 ist gefallen — vielleicht haben wir den Absprung nur verschoben statt beseitigt. Wir schauen noch eine Woche zu."},"tr":{"title":"Daha kısa bir eğitim deniyoruz. 2. gün sayıları tuhaf","summary":"Daha kısa bir eğitim deniyoruz. 2. gün sayıları tuhaf","note":"Çok daha kısa bir eğitim deniyoruz. 2. gün dönüş iyi ama 3. gün düştü, yani kopuşu ortadan kaldırmak yerine sadece ötelemiş olabiliriz. Bir hafta daha izleyeceğiz."}}'::jsonb, 'en', null, null, null, now() - interval '2 days', '{"value":2,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('u3', 'update', 'whow', null, 'wh-mira', null, null, null, array['Art pipeline']::text[], '{}'::text[], null, null, '{"en":{"title":"Our new icon set is 40% smaller after one pass with an optimiser","summary":"Our new icon set is 40% smaller after one pass with an optimiser","note":"Ran the whole icon set through an SVG optimiser and it came out 40% smaller with no visible difference. Nothing clever, just nobody had done it."},"ko":{"title":"아이콘 세트를 최적화 한 번 돌렸더니 40% 줄었어요","summary":"아이콘 세트를 최적화 한 번 돌렸더니 40% 줄었어요","note":"SVG 최적화를 아이콘 세트 전체에 한 번 돌렸더니 눈에 띄는 차이 없이 용량이 40% 줄었어요. 대단한 건 아니고, 그냥 아무도 안 해봤던 거예요."},"de":{"title":"Unser Icon-Set ist nach einem Optimierer-Durchlauf 40% kleiner","summary":"Unser Icon-Set ist nach einem Optimierer-Durchlauf 40% kleiner","note":"Das ganze Icon-Set einmal durch einen SVG-Optimierer geschickt: 40% kleiner, kein sichtbarer Unterschied. Nichts Cleveres, es hatte nur nie jemand gemacht."},"tr":{"title":"İkon setimiz bir optimizasyon turundan sonra %40 küçüldü","summary":"İkon setimiz bir optimizasyon turundan sonra %40 küçüldü","note":"Tüm ikon setini bir SVG optimize ediciden geçirdik, gözle görülür fark olmadan %40 küçüldü. Zekice bir şey değil, sadece kimse yapmamıştı."}}'::jsonb, 'en', null, null, null, now() - interval '4 days', '{"value":4,"unit":"day"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('x1', 'project', 'doubleu', null, 'du-minwoo', null, null, null, array['Slack pipeline','AI video pipeline']::text[], '{}'::text[], null, null, '{"en":{"title":"AI video pipeline on Slack — how Dave, Jiny and Blitz are built","summary":"Three bots, one shape: fully automatic, approval-gated, or fast.","made":"A Slack-native AI video pipeline. Three bots share one shape — Dave runs fully automatic, Jiny pauses for approval between steps, Blitz is the fast API-only track. Trigger by keyword in the channel; every stage posts back to Slack as it happens.","constraints":"Built around AI subscriptions we already pay for — not the fastest setup, the most cost-effective one. The computer should keep producing videos unattended; nobody babysits a render.","solved":"Custom Python + Slack Bolt (Socket Mode), no n8n, no Workflow Builder. Sequential function calls — Gemini 2.5 plans scenes, GPT Image renders keyframes, Seedance renders video. A waiting_for marker decides what each incoming message means. Files hand off as plain paths on local disk — no queue, no database.","borrow":"The waiting_for pattern for reading Slack messages in context, and the submit → poll → verify unit for slow render steps (with retry that checks whether the previous attempt actually finished — no wasted credits)."},"ko":{"title":"Slack 에서 도는 AI 영상 파이프라인 — Dave, Jiny, Blitz를 어떻게 만들었는지","summary":"봇 셋, 한 구조: 전자동·승인대기·고속.","made":"Slack 에서 바로 돌는 AI 영상 파이프라인. 봇 셋이 한 구조를 공유합니다 — Dave는 전자동, Jiny는 단계 사이에 승인을 기다리고, Blitz는 API만 쓰는 고속 트랙입니다. 채널에서 키워드로 시작하고, 모든 단계가 진행되는 대로 Slack에 다시 올라옵니다.","constraints":"이밌 들어가고 있는 AI 구독을 기준으로 짜습니다 — 가장 뱠른 구성이 아니라 가장 남는 구성으로. 사람이 붙지 않아도 컴퓰톰가 알아서 영상을 계속 만들어야 합니다.","solved":"n8n도 Workflow Builder도 안 쓰고 Python + Slack Bolt(Socket Mode)로 직접 만들었습니다. 상태기계 없이 순서대로 함수 호출 — Gemini 2.5가 장면을 짜고, GPT Image가 키프레임을, Seedance가 영상을 렌더합니다. waiting_for 표지로 들어오는 메시지가 무엇을 뜻하는지 결정합니다. 파일은 로얼 디스킬의 경로만 넘깁니다 — 큐도 DB도 없습니다.","borrow":"Slack 메시지를 문맥 안에서 읽는 waiting_for 패턴, 그리고 느린 렌더 단계를 위한 제산 → 폴링 → 검증 단위(지난 시도가 실제로 끝났는지 확인하는 재시도 — 헛된 툴 크레딧 없이)."},"de":{"title":"KI-Videopipeline auf Slack — wie Dave, Jiny und Blitz gebaut sind","summary":"Drei Bots, eine Form: vollautomatisch, mit Freigabe, oder schnell.","made":"Eine Slack-native KI-Videopipeline. Drei Bots teilen eine Form — Dave läuft vollautomatisch, Jiny hält zwischen den Schritten für eine Freigabe an, Blitz ist die schnelle Spur nur über API. Start per Stichwort im Kanal; jede Stufe meldet sich in Slack zurück, während sie läuft.","constraints":"Gebaut um KI-Abos, die wir schon bezahlen — nicht das schnellste Setup, das wirtschaftlichste. Der Rechner soll unbeaufsichtigt weiter Videos produzieren; niemand sitzt bei einem Render daneben.","solved":"Eigenes Python + Slack Bolt (Socket Mode), kein n8n, kein Workflow Builder. Sequenzielle Funktionsaufrufe — Gemini 2.5 plant die Szenen, GPT Image rendert Keyframes, Seedance rendert das Video. Ein waiting_for-Marker entscheidet, was eine eingehende Nachricht bedeutet. Dateien werden als reine Pfade auf der lokalen Platte weitergegeben — keine Queue, keine Datenbank.","borrow":"Das waiting_for-Muster, um Slack-Nachrichten im Kontext zu lesen, und die Einheit aus abschicken → pollen → prüfen für langsame Render-Schritte (mit einem Retry, der erst nachsieht, ob der vorige Versuch nicht doch fertig geworden ist — keine verbrannten Credits)."},"tr":{"title":"Slack üzerinde yapay zekâ video hattı — Dave, Jiny ve Blitz nasıl kuruldu","summary":"Üç bot, tek bir biçim: tam otomatik, onay bekleyen ya da hızlı.","made":"Slack içinde çalışan bir yapay zekâ video hattı. Üç bot aynı biçimi paylaşıyor — Dave tam otomatik, Jiny adımlar arasında onay için duruyor, Blitz yalnızca API kullanan hızlı hat. Kanalda anahtar kelimeyle başlıyor; her aşama olurken Slack’e geri düşüyor.","constraints":"Zaten ödediğimiz yapay zekâ aboneliklerinin etrafında kuruldu — en hızlı kurulum değil, en hesaplı olanı. Bilgisayar kimse başında durmadan video üretmeye devam etmeli.","solved":"Özel Python + Slack Bolt (Socket Mode); n8n yok, Workflow Builder yok. Sıralı fonksiyon çağrıları — Gemini 2.5 sahneleri planlıyor, GPT Image ana kareleri, Seedance videoyu üretiyor. Bir waiting_for işaretleçi, gelen her mesajın ne anlama geldiğine karar veriyor. Dosyalar yerel diskte düz yol olarak devrediliyor — kuyruk da veritabanı da yok.","borrow":"Slack mesajlarını bağlam içinde okumak için waiting_for kalıbı ve yavaş render adımları için gönder → yokla → doğrula birimi (önceki denemenin gerçekten bitip bitmediğini kontrol eden bir yeniden deneme ile — boşa kredi harcamadan)."}}'::jsonb, 'en', null, '{"path":"assets/doubleu-pipeline-cover.png","fit":"contain","bg":"#1e2760"}'::jsonb, null, now() - interval '5 weeks', '{"value":5,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('x2', 'project', 'whow', 'du-minwoo', 'wh-bengt', 'x1', 'appliedFrom', 'Same idea, different stack — n8n Cloud instead of a local codebase, and the support team drives it themselves.', array['Slack pipeline','AI social pipeline']::text[], '{}'::text[], null, null, '{"en":{"title":"Self-serve social asset generator on n8n — built from the Slack pipeline idea","summary":"The support team makes on-brand assets from Slack, unattended.","made":"A self-serve generator where the support team creates on-brand social assets (stills and 5-second videos) directly from Slack. A /jackpot command opens a structured modal; results post back into the same thread. Built on n8n Cloud + kie.ai — no local codebase, no server to babysit.","constraints":"Fully unattended operation for a social-casino product — cost, access, and compliance checks wired in before any spend. No art team involvement per request. Video rendering takes minutes, so the slow step needed hang guards and a bounded worst case (~7-8 min per request).","solved":"One n8n workflow (76 nodes) handles routing, generation, and delivery. Structured modal input removes free-text parsing errors. A 7-point vision QA gate checks every image before posting (retry twice, then flag — never silently). The approved still becomes frame 1 of the video, keeping the character consistent. Each request is an isolated execution — parallel requests never collide.","borrow":"The credit gate pattern (soft warning, then hard stop before any spend) and the fail-open QA design are liftable as-is. Typed input from the start removes a whole class of routing errors."},"ko":{"title":"n8n 으로 만든 셀프서버스 소셜 에셋 생성기 — Slack 파이프라인 아이디어에서","summary":"지원팀이 Slack 에서 밍그에 맞는 에셋을 사람 없이 만듭니다.","made":"지원팀이 Slack 에서 바로 밍그에 맞는 소셜 에셋(이미지와 5초 영상)을 만드는 셀프서버스 생성기. /jackpot 명령이 구조화된 모달을 여고, 결과는 같은 쓰레드로 돌아옵니다. n8n Cloud + kie.ai 기반 — 로여 코드도, 관리할 서버도 없습니다.","constraints":"소셜 카지노 제품이니 완전 방치 운용이 전제 — 보상 지출 전에 버진·접근 권한·켤필라이언스 점검을 먼저 개니다. 요정마다 아트팀이 붙지 않습니다. 영상 렌더가 수 분 걸리니, 느린 단계에는 멈쵤 방지와 최악 상황 상한(요정당 7~8분)이 필요했습니다.","solved":"n8n 워플로우 하나(76노드)가 라우팝·생성·전달을 다 맡습니다. 구조화된 모달 입력으로 자유 텍스트 파싱 오류가 사라집니다. 7개 항목 뱄전 QA 게이트가 모든 이미지를 게시 전에 점검합니다(두 번 재시도, 그런 다음 표시 — 조용히 넘기지 않습니다). 승인된 이미지가 영상의 1프레임이 되어 캠릭터가 유지됩니다. 요정마다 독립 실행이라 동시 요정이 서로 엉키지 않습니다.","borrow":"툴 크레딧 게이트 패턴(경고 한 번, 그리고 지출 전 완전 정지)과 fail-open QA 설계는 그대로 가지셔도 됩니다. 처음부터 타이프된 입력을 받으면 라우팝 오류 한 부류가 통째로 사라집니다."},"de":{"title":"Self-Service-Generator für Social Assets auf n8n — aus der Slack-Pipeline-Idee","summary":"Das Support-Team baut markenkonforme Assets aus Slack, unbeaufsichtigt.","made":"Ein Self-Service-Generator, mit dem das Support-Team markenkonforme Social Assets (Stills und 5-Sekunden-Videos) direkt aus Slack erzeugt. Ein /jackpot-Befehl öffnet ein strukturiertes Modal; die Ergebnisse landen im selben Thread. Auf n8n Cloud + kie.ai — keine lokale Codebasis, kein Server zu betreuen.","constraints":"Vollständig unbeaufsichtigter Betrieb für ein Social-Casino-Produkt — Kosten, Zugriff und Compliance werden geprüft, bevor Geld ausgegeben wird. Kein Art-Team pro Anfrage. Video-Rendering dauert Minuten, der langsame Schritt brauchte also Hänger-Schutz und einen begrenzten schlechtesten Fall (~7-8 Min pro Anfrage).","solved":"Ein n8n-Workflow (76 Nodes) macht Routing, Erzeugung und Auslieferung. Strukturierte Modal-Eingabe nimmt Parsing-Fehler aus Freitext heraus. Ein Vision-QA-Gate mit sieben Punkten prüft jedes Bild vor dem Posten (zweimal wiederholen, dann markieren — nie stillschweigend). Das freigegebene Still wird Frame 1 des Videos und hält die Figur konstant. Jede Anfrage ist eine eigene Ausführung — parallele Anfragen kollidieren nie.","borrow":"Das Credit-Gate-Muster (erst eine Warnung, dann harter Stopp vor jeder Ausgabe) und das Fail-open-QA-Design lassen sich unverändert übernehmen. Typisierte Eingabe von Anfang an nimmt eine ganze Klasse von Routing-Fehlern heraus."},"tr":{"title":"n8n üzerinde kendin-yap sosyal içerik üreteci — Slack hattı fikrinden","summary":"Destek ekibi Slack’ten, kimse başında durmadan marka uyumlu içerik üretiyor.","made":"Destek ekibinin marka uyumlu sosyal içerikleri (görseller ve 5 saniyelik videolar) doğrudan Slack’ten ürettiği kendin-yap bir üreteç. /jackpot komutu yapılandırılmış bir modal açıyor; sonuçlar aynı thread’e dönüyor. n8n Cloud + kie.ai üzerinde — yerel kod tabanı yok, bakılacak sunucu yok.","constraints":"Sosyal kumar ürünü için tamamen gözetimsiz çalışma — harcama öncesinde maliyet, erişim ve uyumluluk kontrolleri devrede. Her istek için sanat ekibi devreye girmiyor. Video render dakikalar aldığı için yavaş adım takılma koruması ve sınırlı bir en kötü durum (istek başına ~7-8 dk) gerektirdi.","solved":"Tek bir n8n akışı (76 düğüm) yönlendirme, üretim ve teslimi yapıyor. Yapılandırılmış modal girdisi serbest metin ayrıştırma hatalarını ortadan kaldırıyor. Yedi maddelik bir görü QA kapısı her görseli paylaşmadan önce denetliyor (iki kez yeniden dene, sonra işaretle — asla sessizce geçme). Onaylanan görsel videonun 1. karesi oluyor, karakter tutarlı kalıyor. Her istek ayrı bir çalışma — paralel istekler çarpışmıyor.","borrow":"Kredi kapısı kalıbı (önce yumuşak uyarı, sonra harcamadan önce kesin duruş) ve fail-open QA tasarımı olduğu gibi alınabilir. Baştan tiplenmiş girdi, bir sınıf yönlendirme hatasını tamamen ortadan kaldırıyor."}}'::jsonb, 'en', null, '{"path":"assets/whow-n8n-cover.png","fit":"contain","bg":"#ffffff"}'::jsonb, null, now() - interval '2 weeks', '{"value":2,"unit":"week"}'::jsonb);
insert into knowledge_items (id, type, origin_studio_id, shared_by_id, documented_by_id, derived_from_id, relation_type, relation_note, keywords, related_to, status, asked_to_studio_id, body, source_lang, conversation, image, link, created_at, demo_age) values ('x3', 'project', 'doubleu', 'wh-bengt', 'du-minwoo', 'x2', 'appliedFrom', 'Four ideas from Whow’s build — threading, progress pings, the QA gate, concurrency — retuned and running in ours.', array['Slack pipeline','Thread']::text[], '{}'::text[], null, null, '{"en":{"title":"What we built from Whow’s note — four ideas now in production","summary":"Four ideas from Whow’s build, retuned and running in ours.","made":"A follow-up deck for Whow showing what we applied from their Architecture Overview — threaded delivery, progress pings, the self-QA gate, and concurrency — and how each was retuned to fit our stack.","constraints":"Our two tracks are built differently — one talks to APIs, the other drives a browser — with very different render times. And our trigger is a name, not a slash command, so the thread root needed rethinking.","solved":"The actual brief (not the bot confirmation) becomes the thread root, so channel previews are scannable. Progress pings calibrated per track: 1/5/10 min on the API track, 2/10/30/50 min on the browser track. QA gate kept to four checks, one retry with failure reasons, fail-open. Concurrency shipped in two forms — parallel per thread on Blitz, queued with position on Dave/Jiny.","borrow":"The thread-root reorder — Whow plans to take it back into their own generator. And the retuning pattern itself: the same idea usually needs different numbers on a different stack.","next":"Credit gate and cross-model fallback, sequenced behind full multi-user concurrency."},"ko":{"title":"Whow의 노트에서 우리가 만든 것 — 4개 아이디어 실제 가동 중","summary":"Whow의 시스템에서 가져온 4개 아이디어, 우리에 맞게 조정되어 가동 중.","made":"Whow의 Architecture Overview에서 적용한 것들을 보여주는 후속 문서 — 스레드 전달, 진행 알림, self-QA 게이트, 동시성 — 각각을 우리 스택에 맞게 재조정한 과정 포함.","constraints":"우리 두 트랙은 구조가 다릅니다 — 하나는 API, 하나는 브라우저를 구동하고 렌더 시간도 크게 다릅니다. 트리거도 슬래시 명령이 아닌 이름이라 스레드 루트를 다시 생각해야 했습니다.","solved":"봇 확인 메시지가 아니라 실제 브리프가 스레드 루트가 되어 채널 미리보기를 한눈에 읽을 수 있습니다. 진행 알림은 트랙별 보정: API 트랙 1/5/10분, 브라우저 트랙 2/10/30/50분. QA 게이트는 4개 검사, 실패 사유를 첨부한 재생성 1회, fail-open. 동시성은 두 형태 — Blitz는 스레드별 병렬, Dave/Jiny는 순번 안내 대기열.","borrow":"스레드 루트 재배치 — Whow가 자기 생성기로 다시 가져갈 예정입니다. 그리고 재조정 패턴 자체: 같은 아이디어도 다른 스택에서는 대개 다른 숫자가 필요합니다.","next":"크레딧 게이트와 크로스모델 폴백 — 완전한 멀티유저 동시성 다음 순서로."},"de":{"title":"Was wir aus Whows Notiz gebaut haben — vier Ideen jetzt im Betrieb","summary":"Vier Ideen aus Whows Bau, nachjustiert und bei uns im Einsatz.","made":"Ein Follow-up-Deck für Whow, das zeigt, was wir aus ihrem Architecture Overview übernommen haben — Auslieferung im Thread, Fortschrittsmeldungen, das Self-QA-Gate und Parallelität — und wie jedes davon auf unseren Stack nachjustiert wurde.","constraints":"Unsere zwei Spuren sind unterschiedlich gebaut — eine spricht mit APIs, die andere steuert einen Browser — mit sehr unterschiedlichen Renderzeiten. Und unser Auslöser ist ein Name, kein Slash-Befehl, also musste die Thread-Wurzel neu gedacht werden.","solved":"Der eigentliche Brief (nicht die Bot-Bestätigung) wird zur Thread-Wurzel, damit die Kanal-Vorschau überfliegbar bleibt. Fortschrittsmeldungen pro Spur kalibriert: 1/5/10 Min auf der API-Spur, 2/10/30/50 Min auf der Browser-Spur. Das QA-Gate bleibt bei vier Prüfungen, ein Retry mit Fehlergründen, fail-open. Parallelität in zwei Formen — parallel pro Thread bei Blitz, Warteschlange mit Position bei Dave/Jiny.","borrow":"Die neue Thread-Wurzel — Whow will sie in den eigenen Generator zurückholen. Und das Nachjustieren selbst: dieselbe Idee braucht auf einem anderen Stack meist andere Zahlen.","next":"Credit-Gate und Cross-Model-Fallback, eingereiht hinter voller Mehrnutzer-Parallelität."},"tr":{"title":"Whow’un notundan ne kurduk — dört fikir artık üretimde","summary":"Whow’un yapısından dört fikir, bize göre ayarlanmış ve bizde çalışıyor.","made":"Whow için bir takip sunumu — Architecture Overview’larından neleri uyguladığımızı gösteriyor: thread içinde teslim, ilerleme bildirimleri, self-QA kapısı ve eşzamanlılık — ve her birinin bizim yapımıza göre nasıl yeniden ayarlandığı.","constraints":"İki hattımız farklı kurulmuş — biri API’lerle konuşuyor, diğeri bir tarayıcı sürüyor — render süreleri de çok farklı. Üstelik tetikleyicimiz slash komutu değil bir isim; thread kökünü yeniden düşünmek gerekti.","solved":"Thread kökü bot onayı değil asıl brief oluyor; böylece kanal önizlemeleri bir bakışta okunuyor. İlerleme bildirimleri hat başına ayarlandı: API hattında 1/5/10 dk, tarayıcı hattında 2/10/30/50 dk. QA kapısı dört kontrolde tutuldu; hata gerekçeleriyle bir kez yeniden deneme, fail-open. Eşzamanlılık iki biçimde geldi — Blitz’te thread başına paralel, Dave/Jiny’de sıra numaralı kuyruk.","borrow":"Thread kökü düzenlemesi — Whow bunu kendi üretecine geri almayı planlıyor. Bir de yeniden ayarlama kalıbının kendisi: aynı fikir farklı bir yapıda çoğu zaman farklı sayılar ister.","next":"Kredi kapısı ve modeller arası yedek — tam çok kullanıcılı eşzamanlılığın hemen ardından sırada."}}'::jsonb, 'en', null, null, null, now(), '{"value":0,"unit":"day","justNow":true}'::jsonb);
